          added += 1;
        }
        idleRounds = added === 0 ? idleRounds + 1 : 0;

        emit(STATES.CHECK_NEXT, {
          pageCount: pageCount,
          idleRounds: idleRounds,
          added: added
        });

        if (isCancelled()) return abort(REASONS.CANCELLED);

